    val data: JsonObject by lazy {
        require(sha256(dataText.toByteArray()) == DATA_SHA256)
        strictObject(dataText, 1_000_000).also {
            require(it.getValue("artifacts").jsonObject.size == 89 && it.getValue("placements").jsonObject.size == 90 && it.getValue("resolutions").jsonArray.size == 165)
        }
    }
    val artifacts: Map<String,JsonObject> get() = data.getValue("artifacts").jsonObject.mapValues { it.value.jsonObject }
    val placements: Map<String,String> get() = data.getValue("placements").jsonObject.mapValues { it.value.jsonPrimitive.content }
    val manifest: JsonObject get() = data.getValue("manifest").jsonObject
    val integrity: String get() = artifacts.getValue("$PACKAGE@$VERSION").getValue("integrity").jsonPrimitive.content
    fun supports(recipe: WorkstationInstallRecipe): Boolean = recipe.familyId == FAMILY && recipe.version == VERSION &&
        recipe.packageName == PACKAGE && recipe.packageVersion == VERSION && recipe.command == COMMAND && recipe.minimumNodeMajor == 22 && recipe.provenanceUrl == PROVENANCE &&
        !recipe.allowLifecycleScripts && recipe.lifecycleScriptReview == null && recipe.additionalDependencies == mapOf("typescript" to TYPESCRIPT_VERSION,
            "@vue/typescript-plugin" to VERSION, "typescript-language-server" to TSLSP_VERSION) && recipe.registryIntegrity == integrity
    fun recipe() = WorkstationInstallRecipe(FAMILY, VERSION, PACKAGE, VERSION, COMMAND, 22, PROVENANCE,
        registryIntegrity = integrity, additionalDependencies = mapOf("typescript" to TYPESCRIPT_VERSION,
            "@vue/typescript-plugin" to VERSION, "typescript-language-server" to TSLSP_VERSION))
    fun review(): JsonObject = buildJsonObject {
        val recipe=recipe()
        put("schema",1);put("familyId",FAMILY);put("version",VERSION);put("packageName",PACKAGE)
        put("packageVersion",VERSION);put("registryIntegrity",integrity);put("provenanceUrl",PROVENANCE)
        put("allowLifecycleScripts",false);put("additionalDependencies",buildJsonObject { recipe.additionalDependencies.forEach { (k,v)->put(k,v) } })
        put("policy",PROFILE);put("archivePolicySha256",DATA_SHA256);put("helperDependency",LocalUbuntuVueHelperPolicy.KEY)
    }
    fun requireReview(value: JsonObject) { require(value == review()) { "Vue reviewed recipe identity changed" } }
    fun isFamily(family: String) = family == FAMILY || family == LocalUbuntuVueHelperPolicy.FAMILY
    fun version(family: String): String = when(family) { FAMILY -> VERSION; LocalUbuntuVueHelperPolicy.FAMILY -> LocalUbuntuVueHelperPolicy.VERSION; else -> error("Unknown Vue family") }
    fun strictObject(text: String, max: Int = MAX_JSON_BYTES): JsonObject = LocalUbuntuSveltePolicy.strictObject(text, max)
    fun safeRelative(path: String) {
        require(path.toByteArray(Charsets.UTF_8).size in 1..4096 && path.split('/').size <= 64 && !path.startsWith('/') && !path.endsWith('/'))
        require(path.none { it.code < 32 || it.code == 127 || it == '\\' || it == ':' } && path.split('/').none { it.isEmpty() || it == "." || it == ".." })
    }
    fun sha256(bytes: ByteArray): String = MessageDigest.getInstance("SHA-256").digest(bytes).joinToString("") { "%02x".format(it.toInt() and 255) }
    fun read(file: File, max: Int = MAX_JSON_BYTES): String = LocalUbuntuSveltePolicy.readRegular(file,max)
    fun requirePackage(identity: String, value: JsonObject) {
        val expected = artifacts.getValue(identity).getValue("metadata").jsonObject
        expected.forEach { (key,want) ->
            val raw=value[key] ?: JsonNull
            fun normalized(bin: JsonElement): JsonElement = if(key == "bin" && bin is JsonPrimitive && bin.isString)
                buildJsonObject { put(expected.getValue("name").jsonPrimitive.content.substringAfterLast('/'),bin) } else bin
            require(normalized(raw) == normalized(want)) { "Vue original package metadata differs: $identity/$key" }
        }
        // Bundled TS-LSP is a five-file published bundle. Its build-time Rollup dependencies
        // are source attribution candidates, not invented on-disk npm prerequisites.
        require(value["name"] == expected["name"] && value["version"] == expected["version"])
    }
    fun requireGraph() {
        val slots = placements
        fun resolve(parent: String, name: String): String? {
            var at = parent
            while(true) {
                if(!at.endsWith("node_modules")) "$at/node_modules/$name".takeIf { it in slots }?.let { return it }
                if('/' !in at) break
                at = at.substringBeforeLast('/')
            }
            return "node_modules/$name".takeIf { it in slots }
        }
        data.getValue("resolutions").jsonArray.forEach { raw ->
            val e = raw.jsonObject
            fun s(key: String) = e.getValue(key).jsonPrimitive.content
            require(slots[s("parent")] == s("identity") && resolve(s("parent"),s("key")) == s("target") && slots[s("target")] == s("target_identity"))
        }
    }
    /** Archive proof is generated after authenticated extraction, then bound to the durable
     * receipt by the complete installation seal. Every file, directory, placement and edge
     * is freshly checked; package.json-only and partial-closure proofs are insufficient. */
    fun validateInstalledLayout(stage: File, proof: JsonObject, active: () -> Unit = {}): JsonObject {
        requireGraph()
        require(proof.keys == setOf("schema","policy","archives") && proof["schema"] == JsonPrimitive(1) && proof["policy"] == JsonPrimitive(DATA_SHA256))
        val archiveProofs = proof.getValue("archives").jsonObject
        require(archiveProofs.keys == artifacts.keys)
        val expected = linkedMapOf<String,JsonObject>()
        val originalDirs = linkedSetOf<String>()
        placements.forEach { (slot,identity) ->
            active()
            val p = archiveProofs.getValue(identity).jsonObject
            require(p.keys == setOf("sha512","files","directories") && p["sha512"] == artifacts.getValue(identity)["sha512"])
            p.getValue("directories").jsonArray.forEach { raw ->
                val path=raw.jsonPrimitive.content; safeRelative(path); require(path.split('/').none{it=="node_modules"}); originalDirs += "$slot/$path"
            }
            val files = p.getValue("files").jsonObject
            require(files.isNotEmpty() && "package.json" in files && files.size <= MAX_FILES)
            files.forEach { (relative,raw) ->
                safeRelative(relative)
                require(relative.split('/').none { it == "node_modules" })
                val value = raw.jsonObject
                require(value.keys == setOf("size","sha256") && value.getValue("size").jsonPrimitive.long in 0..MAX_ARCHIVE_UNPACKED &&
                    value.getValue("sha256").jsonPrimitive.content.matches(Regex("[0-9a-f]{64}")))
                require(expected.put("$slot/$relative",value) == null)
            }
        }
        require(expected.size <= MAX_FILES)
        val npm = File(stage,NPM_ROOT)
        require(read(File(npm,"package.json")) == manifest.toString())
        val allowedDirs = linkedSetOf("").apply { addAll(originalDirs) }
        (expected.keys + originalDirs + "package.json").forEach { path ->
            var parent = path.substringBeforeLast('/',"")
            while(parent.isNotEmpty()) { allowedDirs += parent; parent = parent.substringBeforeLast('/',"") }
        }
        val seen = linkedSetOf<String>(); val seenDirs = linkedSetOf<String>(); var count = 0; var total = 0L
        val deadline = System.nanoTime() + 30_000_000_000L
        fun walk(file: File, path: String) {
            active(); require(System.nanoTime() <= deadline && ++count <= MAX_ENTRIES)
            val attrs = Files.readAttributes(file.toPath(),BasicFileAttributes::class.java,NOFOLLOW_LINKS)
            require(!attrs.isSymbolicLink)
            if(attrs.isDirectory) {
                require(path in allowedDirs && seenDirs.add(path)) { "Unreviewed Vue directory: $path" }
                requireNotNull(file.listFiles()).sortedBy { it.name }.forEach { walk(it,if(path.isEmpty())it.name else "$path/${it.name}") }
            } else {
                require(attrs.isRegularFile && seen.add(path))
                if(path == "package.json") return
                val want = expected[path] ?: error("Unreviewed Vue file: $path")
                total = Math.addExact(total,attrs.size()); require(total <= MAX_TREE_BYTES)
                val measured = NimRuntimeClosure.measure(file,MAX_ARCHIVE_UNPACKED,active)
                require(measured.first == want.getValue("size").jsonPrimitive.long && measured.second == want.getValue("sha256").jsonPrimitive.content)
            }
        }
        walk(npm,"")
        require(seen == expected.keys + "package.json" && seenDirs == allowedDirs)
        placements.forEach { (slot,identity) -> requirePackage(identity,strictObject(read(File(npm,"$slot/package.json")))) }
        listOf(VUE_ENTRY,TSLSP_ENTRY,TS_ENTRY,TS_LIBRARY,PLUGIN_ENTRY).forEach { require(File(stage,it).isFile) }
        return proof
    }
    fun validateInstalledLayout(stage: File, active: () -> Unit = {}): JsonObject =
        validateInstalledLayout(stage, strictObject(read(File(stage,PROOF_FILE),8_000_000),8_000_000), active)
}
